select qs.id,gs.id,t.id,$q$Polícia Civil do Ceará – Delegado de Polícia Civil$q$,2025,$q$Delegado de Polícia Civil$q$,$q$Cebraspe$q$,v.n,v.subj,v.txt,v.txt,v.ans,v.pg,v.st,v.legal,v.ctx,v.note
from (values (97,$q$Conhecimentos do cargo de Delegado$q$,$q$De acordo com o Decreto n.º 6.514/2008, a sanção de advertência poderá ser aplicada em razão do cometimento de infrações administrativas contra o meio ambiente, mediante a lavratura de auto de infração, quando
(A) a multa por unidade de medida for equivalente a um salário mínimo.
(B) a multa consolidada for equivalente a um salário mínimo.
(C) a multa por unidade de medida não exceder o valor de mil reais.
(D) não couber a aplicação da sanção de multa.
(E) o prazo para sanar irregularidades for inferior a seis meses.$q$,$q$C$q$,17,$q$under_review$q$,false,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(98,$q$Conhecimentos do cargo de Delegado$q$,$q$Segundo a Lei n.º 9.605/1998, é circunstância que agrava a pena por crime ambiental, quando não o constitui ou o qualifica, o fato de o agente tê-lo praticado
(A) de forma a atingir espécies nativas.
(B) em colaboração com agentes encarregados da vigilância ambiental.
(C) em período de defeso à fauna.
(D) em concurso de pessoas.
(E) após o cometimento de duas ou mais infrações ambientais.$q$,$q$C$q$,17,$q$under_review$q$,false,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(99,$q$Conhecimentos do cargo de Delegado$q$,$q$Assinale a opção correspondente à categoria de unidade de conservação definida pela Lei n.º 9.985/2000 como área em geral de pequena extensão, com pouca ou nenhuma ocupação humana, com características naturais extraordinárias ou que abriga exemplares raros da biota regional, e destinada ao objetivo de manter os ecossistemas naturais de importância regional ou local e regular o seu uso admissível, de modo a compatibilizá-lo com os objetivos de conservação da natureza.
(A) área de relevante interesse ecológico
(B) estação ecológica
(C) área de proteção ambiental
(D) reserva de desenvolvimento sustentável
(E) reserva particular do patrimônio natural$q$,$q$A$q$,17,$q$under_review$q$,false,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(100,$q$Conhecimentos do cargo de Delegado$q$,$q$O dever de recuperar ou indenizar os danos causados ao meio ambiente, independentemente da existência de culpa, é um atributo característico da
(A) reparação integral.
(B) responsabilidade subjetiva.
(C) tríplice responsabilidade.
(D) responsabilidade objetiva.
(E) teoria do dano integral.$q$,$q$D$q$,17,$q$under_review$q$,false,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$)) v(n,subj,txt,ans,pg,st,legal,ctx,note)
